using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.Localization;using UnityEngine.Localization;using UnityEngine.Localization.Settings;using UnityEngine.Localization.Tables;using UnityEngine.Localization.Metadata;using Mewgic.Localization;using Mewgic.UI;using TMPro;
public static class Part12CLocalization
{
 [Serializable]public sealed class Row{public string key,review;public bool plain;public Dictionary<string,string> values;}
 public static Row[] Source()=>Newtonsoft.Json.JsonConvert.DeserializeObject<Row[]>(File.ReadAllText("Assets/Localization/Source/Mewgic.json"));
 public static void Install()
 {
  if(EditorApplication.isPlaying)throw new Exception("Play Mode durdurulmalı");Directory.CreateDirectory("Assets/Localization/Tables");Directory.CreateDirectory("Assets/Localization/Locales");AssetDatabase.Refresh();
  var settings=AssetDatabase.LoadAssetAtPath<LocalizationSettings>("Assets/Localization/LocalizationSettings.asset");if(settings==null){settings=ScriptableObject.CreateInstance<LocalizationSettings>();AssetDatabase.CreateAsset(settings,"Assets/Localization/LocalizationSettings.asset");}LocalizationEditorSettings.ActiveLocalizationSettings=settings;
  foreach(var code in L.Codes){var locale=LocalizationEditorSettings.GetLocale(code);if(locale==null){locale=Locale.CreateLocale(code);AssetDatabase.CreateAsset(locale,"Assets/Localization/Locales/"+code+".asset");LocalizationEditorSettings.AddLocale(locale);}locale.LocaleName=L.Names[Array.IndexOf(L.Codes,code)];EditorUtility.SetDirty(locale);}
  var en=LocalizationEditorSettings.GetLocale("en");foreach(var locale in LocalizationEditorSettings.GetLocales())if(locale!=en&&locale.Metadata.GetMetadata<FallbackLocale>()==null){locale.Metadata.AddMetadata(new FallbackLocale(en));EditorUtility.SetDirty(locale);}
  LocalizationSettings.StringDatabase.SmartFormatter=UnityEngine.Localization.SmartFormat.Smart.CreateDefaultSmartFormat();LocalizationSettings.ProjectLocale=en;LocalizationSettings.StringDatabase.UseFallback=true;LocalizationSettings.StartupLocaleSelectors.Clear();LocalizationSettings.StartupLocaleSelectors.Add(new SavedLocaleSelector());LocalizationSettings.StartupLocaleSelectors.Add(new DeviceLocaleSelector());LocalizationSettings.StartupLocaleSelectors.Add(new SpecificLocaleSelector{LocaleId="en"});LocalizationSettings.InitializeSynchronously=false;EditorUtility.SetDirty(settings);
  var collection=LocalizationEditorSettings.GetStringTableCollection(L.Table)??LocalizationEditorSettings.CreateStringTableCollection(L.Table,"Assets/Localization/Tables");var rows=Source();foreach(string code in L.Codes){var table=(StringTable)collection.GetTable(code);foreach(var row in rows){var entry=table.AddEntry(row.key,row.values[code]);entry.IsSmart=!row.plain;}EditorUtility.SetDirty(table);}EditorUtility.SetDirty(collection.SharedData);collection.SetPreloadTableFlag(true);EditorUtility.SetDirty(collection);
  string corpus=new string(rows.SelectMany(r=>r.values.Values).SelectMany(s=>s).Concat(string.Concat(L.Names)).Where(c=>!char.IsControl(c)).Distinct().ToArray());var fonts=MewgicTypographySettings.Current;foreach(var font in new[]{fonts.heading,fonts.body}){string needed=new string(corpus.Where(c=>!font.HasCharacter(c)).ToArray());if(needed.Length>0){font.atlasPopulationMode=AtlasPopulationMode.Dynamic;var serialized=new SerializedObject(font);serialized.FindProperty("m_SourceFontFile").objectReferenceValue=AssetDatabase.LoadAssetAtPath<Font>("Assets/Art/Typography/"+(font==fonts.heading?"MewgicTitle":"MewgicBody")+".ttf");serialized.ApplyModifiedPropertiesWithoutUndo();font.isMultiAtlasTexturesEnabled=true;if(!font.TryAddCharacters(needed,out string missing)&&!string.IsNullOrEmpty(missing))throw new Exception("Eksik glif: "+font.name+" "+missing);}font.atlasPopulationMode=AtlasPopulationMode.Static;EditorUtility.SetDirty(font);foreach(var atlas in font.atlasTextures){if(!AssetDatabase.Contains(atlas))AssetDatabase.AddObjectToAsset(atlas,font);EditorUtility.SetDirty(atlas);}}
  Directory.CreateDirectory("Assets/Resources/Localization");AssetDatabase.Refresh();if(AssetDatabase.LoadAssetAtPath<Material>("Assets/Resources/Localization/PlayFace.mat")==null){var material=new Material(Shader.Find("Mewgic/LocalizedPlayFace"));AssetDatabase.CreateAsset(material,"Assets/Resources/Localization/PlayFace.mat");}
  var addressables=UnityEditor.AddressableAssets.AddressableAssetSettingsDefaultObject.Settings;addressables.BuildAddressablesWithPlayerBuild=UnityEditor.AddressableAssets.Settings.AddressableAssetSettings.PlayerBuildOption.BuildWithPlayer;EditorUtility.SetDirty(addressables);
  AssetDatabase.SaveAssets();AssetDatabase.ForceReserializeAssets(Directory.GetFiles("Assets/Localization","*.asset",SearchOption.AllDirectories));Validate();
 }
 public static void Validate()
 {
  var rows=Source();var errors=new List<string>();var config=LocalizationEditorSettings.ActiveLocalizationSettings;var selectors=config?.GetStartupLocaleSelectors();if(selectors==null||selectors.Count!=3||selectors.Any(x=>x==null)||!(selectors[0] is SavedLocaleSelector)||!(selectors[1] is DeviceLocaleSelector)||!(selectors[2] is SpecificLocaleSelector))errors.Add("config:başlangıç seçicisi eksik/boş");if(!LocalizationSettings.StringDatabase.UseFallback||LocalizationSettings.ProjectLocale?.Identifier.Code!="en")errors.Add("config:İngilizce fallback kapalı");var formatter=LocalizationSettings.StringDatabase.SmartFormatter;if(formatter==null||formatter.SourceExtensions.Any(x=>x==null)||formatter.FormatterExtensions.Any(x=>x==null))errors.Add("config:SmartFormat uzantısı eksik");if(rows.Select(r=>r.key).Distinct().Count()!=rows.Length)errors.Add("Yinelenen anahtar");var collection=LocalizationEditorSettings.GetStringTableCollection(L.Table);foreach(var code in L.Codes){var table=collection?.GetTable(code) as StringTable;foreach(var row in rows){if(!row.values.TryGetValue(code,out string value)||string.IsNullOrWhiteSpace(value)||table?.GetEntry(row.key)==null||table.GetEntry(row.key).Value!=value||table.GetEntry(row.key).IsSmart==row.plain)errors.Add(code+":"+row.key);foreach(char c in row.values[code])if(!char.IsControl(c)&&(!MewgicTypographySettings.Current.body.HasCharacter(c)||!MewgicTypographySettings.Current.heading.HasCharacter(c)))errors.Add("glyph:"+code+":"+((int)c));}}
  var keys=new HashSet<string>(rows.Select(r=>r.key));foreach(string file in Directory.GetFiles("Assets/Scripts","*.cs",SearchOption.AllDirectories).Where(f=>!f.Contains("Tests"))){foreach(System.Text.RegularExpressions.Match match in System.Text.RegularExpressions.Regex.Matches(File.ReadAllText(file),"L\\.V\\(\\\"(?<key>[a-z0-9_.]+)\\\"")){string key=match.Groups["key"].Value;if(!keys.Contains(key))errors.Add("source:"+file+":"+key);}}
  Directory.CreateDirectory("docs/ProductionReports/Part12C");File.WriteAllText("docs/ProductionReports/Part12C/VALIDATION.json",Newtonsoft.Json.JsonConvert.SerializeObject(new{success=errors.Count==0,keys=rows.Length,locales=L.Codes,errors,translationStatus="Ana dil konuşuru tarafından incelenmemiş ilk taslak"},Newtonsoft.Json.Formatting.Indented));if(errors.Count>0)throw new Exception(string.Join("\n",errors.Take(10)));
 }
}
